const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var chengdu = ee.Geometry.Point([104.066, 30.573]);
  var suining = ee.Geometry.Point([105.573, 30.526]);
  var startDate = '2001-01-01';
  var endDate = '2023-12-31';

  // 2. Data Acquisition - MODIS Terra Aerosol
  var aodCol = ee.ImageCollection('MODIS/061/MOD04_L2')
    .filterDate(startDate, endDate)
    .select('Optical_Depth_Land_And_Ocean');

  // Check collection size
  var count = aodCol.size().getInfo();
  if (count === 0) {
    print("No AOD data found in collection");
    print("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Calculate mean AOD for each city
  var chengduMean = aodCol.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: chengdu,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean');

  var suiningMean = aodCol.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: suining,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean');

  // Get pixel counts to check for valid data
  var chengduCount = aodCol.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: chengdu,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean').getInfo();

  var suiningCount = aodCol.mean().reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: suining,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_Land_And_Ocean').getInfo();

  // Get the mean values
  var chengduVal = chengduMean.getInfo();
  var suiningVal = suiningMean.getInfo();

  // 4. Validation & Final Answer
  print("Chengdu AOD: " + chengduVal?.toFixed(4) + ", Pixels: " + chengduCount);
  print("Suining AOD: " + suiningVal?.toFixed(4) + ", Pixels: " + suiningCount);

  // Check for no valid pixels
  if (chengduCount === 0 || suiningCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for invalid values (AOD should typically be 0-3)
  if (chengduVal === null || suiningVal === null || 
      isNaN(chengduVal) || isNaN(suiningVal) ||
      chengduVal < 0 || chengduVal > 3 || 
      suiningVal < 0 || suiningVal > 3) {
    print("<answer>C3</answer>");
    return;
  }

  // Compare AOD values
  if (chengduVal > suiningVal) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
